import{_ as e,o as t,c as d,ag as n}from"./chunks/framework.Dx86EdC1.js";const m=JSON.parse('{"title":"Masuk & Akun Pengguna","description":"","frontmatter":{},"headers":[],"relativePath":"panduan-pengguna/masuk-akun.md","filePath":"panduan-pengguna/masuk-akun.md","lastUpdated":1791730642000}'),o={name:"panduan-pengguna/masuk-akun.md"};function r(i,a,s,u,c,l){return t(),d("div",null,[...a[0]||(a[0]=[n('<h1 id="masuk-akun-pengguna" tabindex="-1">Masuk &amp; Akun Pengguna <a class="header-anchor" href="#masuk-akun-pengguna" aria-label="Permalink to &quot;Masuk &amp; Akun Pengguna&quot;">​</a></h1><h2 id="masuk-ke-dashboard-admin" tabindex="-1">Masuk ke Dashboard Admin <a class="header-anchor" href="#masuk-ke-dashboard-admin" aria-label="Permalink to &quot;Masuk ke Dashboard Admin&quot;">​</a></h2><ol><li>Buka <code>https://domain-anda/login</code>.</li><li>Masukkan <strong>email atau username</strong> dan <strong>kata sandi</strong>.</li><li>Klik <strong>Masuk</strong>. Pengguna dengan role <code>superadmin</code>, <code>kades</code>, <code>perangkat</code>, atau <code>rt</code> akan diarahkan ke <code>/admin/dashboard</code>.</li></ol><p>Semua akun terotentikasi dapat mengelola <a href="/panduan-pengguna/pengaturan.html">Profil &amp; Kata Sandi</a> di menu profil (halaman <code>/profile</code>).</p><h2 id="akun-website-demo" tabindex="-1">Akun &amp; Website Demo <a class="header-anchor" href="#akun-website-demo" aria-label="Permalink to &quot;Akun &amp; Website Demo&quot;">​</a></h2><p>Aplikasi SiDesa dapat dicoba langsung di <a href="https://sidesa.timacodecraft.com" target="_blank" rel="noreferrer">https://sidesa.timacodecraft.com</a>.</p><p>Tersedia akun demo bawaan berikut (<strong>kata sandi seluruh akun: <code>password</code></strong>):</p><div class="info custom-block"><p class="custom-block-title">Reset Rutin Demo</p><p>Data pada website demo direset otomatis setiap hari pukul <strong>00:00 WIB</strong> ke kondisi awal seeder.</p></div><table tabindex="0"><thead><tr><th>Email</th><th>Username</th><th>Role</th></tr></thead><tbody><tr><td><code>admin@sidesa.timacodecraft.com</code></td><td><code>superadmin</code></td><td>Super Administrator</td></tr><tr><td><code>kades@sidesa.timacodecraft.com</code></td><td><code>kades</code></td><td>Kepala Desa</td></tr><tr><td><code>perangkat@sidesa.timacodecraft.com</code></td><td><code>perangkat</code></td><td>Perangkat Desa (Kasi Pelayanan)</td></tr><tr><td><code>rt@sidesa.timacodecraft.com</code></td><td><code>ketua_rt</code></td><td>Ketua RT 001 / RW 002</td></tr><tr><td><code>warga@sidesa.timacodecraft.com</code></td><td><code>warga</code></td><td>Warga (Budi Santoso)</td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">Produksi</p><p>Hapus atau ganti seluruh kata sandi akun demo sebelum sistem dipakai nyata. Akun demo dibuat oleh <code>database/seeders/UserSeeder.php</code>.</p></div><h2 id="registrasi-akun-warga" tabindex="-1">Registrasi Akun Warga <a class="header-anchor" href="#registrasi-akun-warga" aria-label="Permalink to &quot;Registrasi Akun Warga&quot;">​</a></h2><p>Warga mendaftar sendiri melalui <code>/register</code>:</p><ol><li>Isi data diri (nama, NIK, No KK, kontak, RT/RW).</li><li>Centang <strong>persetujuan pemrosesan data pribadi</strong> (explicit consent sesuai UU PDP No. 27/2022) — pendaftaran ditolak tanpa persetujuan.</li><li>Setelah akun aktif (divalidasi operator), warga dapat masuk dan mengajukan surat di portal layanan mandiri.</li></ol><p>Alternatif: operator dapat membuatkan akun warga dari data penduduk lewat menu <strong>Penduduk → Buat Akun</strong> (<code>POST /admin/residents/{id}/create-account</code>).</p><h2 id="lupa-kata-sandi-akun-terkunci" tabindex="-1">Lupa Kata Sandi / Akun Terkunci <a class="header-anchor" href="#lupa-kata-sandi-akun-terkunci" aria-label="Permalink to &quot;Lupa Kata Sandi / Akun Terkunci&quot;">​</a></h2><p>Saat ini reset kata sandi dilakukan oleh <strong>Superadmin</strong> melalui <strong>Admin → Pengguna</strong> (<code>/admin/users</code>) — ubah kata sandi akun terkait.</p><h2 id="keluar-logout" tabindex="-1">Keluar (Logout) <a class="header-anchor" href="#keluar-logout" aria-label="Permalink to &quot;Keluar (Logout)&quot;">​</a></h2><p>Klik menu profil → <strong>Keluar</strong>. Sesi diakhiri via <code>POST /logout</code>.</p>',18)])])}const p=e(o,[["render",r]]);export{m as __pageData,p as default};
